<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getComboboxContext } from './combobox-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; ref?: HTMLDivElement | null; } let { children, ref = $bindable(null), ...rest }: Props = $props(); const box = getComboboxContext();</script><div bind:this={ref} {...rest} id={box.listId} role="listbox" aria-labelledby={box.labelId} aria-multiselectable={box.multiple || undefined}>{@render children?.()}</div>
